    private void btnReportsActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnReportsActionPerformed
        try (Connection con = DatabaseConnection.getConnection();
             java.io.InputStream input = getClass().getResourceAsStream("/MonthlyReport.jrxml")) {
            net.sf.jasperreports.engine.JasperReport report =
                    net.sf.jasperreports.engine.JasperCompileManager.compileReport(input);
            net.sf.jasperreports.engine.JasperPrint print =
                    net.sf.jasperreports.engine.JasperFillManager.fillReport(report, null, con);
            net.sf.jasperreports.view.JasperViewer.viewReport(print, false);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }//GEN-LAST:event_btnReportsActionPerformed

